///////////////////////////////////////////////////////////////////////////////////
// Velociraptor: ARRAY
//
// Incluir este header 
// com o define VL_ARRAY_INCLUDES_:
//                                     

// 1. defines de constantes matemáticas
//  VL_ARRAY_INCLUDES_MAT_CONSTS
// 2. defines de interior de arrays usuais
//  VL_ARRAY_INCLUDES_USUAL_ARR_DEFS
// 3. declaração de arrays usuais
//  VL_ARRAY_INCLUDES_USUAL_ARR_DECLS
// 4. defines para evitar repetições em arrays e estruturas
//  VL_ARRAY_INCLUDES_REPS
// 5. defines de indices de matrizes sem stride
//  VL_ARRAY_INCLUDES_ROWMAJOR_NS_INDEX
// 6. alinhamento de apontadores e cast
//  VL_ARRAY_INCLUDES_CAST
// 7. defines de operações vetoriais e matriciais 2/3/4
//  VL_ARRAY_INCLUDES_VECOP
// 8. defines de soluções de polinomios com defines
//  VL_ARRAY_INCLUDES_POLYS
// 9. defines de retangulos
//  VL_ARRAY_INCLUDES_BBOX2
// 10. defines de operações de estatistica por acrescimos (sem recalcular)
//  VL_ARRAY_INCLUDES_STATS
// 11. velhas funções desenrasca array/mtx2/mtx3 não optimizadas
//  VL_ARRAY_INCLUDES_POCKET_ARRAY
// 12. velhas funções desenrasca A'*...
//  VL_ARRAY_INCLUDES_POCKET_ATRANSPOSE_MUL
// 13. várias defines e funções misc
//  VL_ARRAY_INCLUDES_POCKET_MISC
// 14. strings de numeros ou tamanhos (K,M,G...) para numeros
//  VL_ARRAY_INCLUDES_STR2NUM_CVT
// 15. algumas funções de rotação dado eixo
//  VL_ARRAY_INCLUDES_GEO_AXIS
// 16. complexos 
//  VL_ARRAY_INCLUDES_COMPLEX
// 17. funções enumeradas
//  VL_ARRAY_INCLUDES_CURVES
// 18. funções de str->num
//  VL_ARRAY_STR2NUM_TEMPLATES     versão c++
//  VL_ARRAY_STR2NUM_IGNORE_BLANKS papa os espaços antes

#ifndef VL_STRY
	#define VL_STRY(X_)	 "" #X_ ""
#endif
#ifndef VL_STRYEXP
	#define VL_STRYEXP_(X_)	 VL_STRY(X_)
	#define VL_STRYEXP(X_)	 VL_STRYEXP_(X_)
#endif
#ifndef VL_MKSTRS
	#define VL_MKSTRS(X_,Y_) VL_STRY(Y_),
#endif 
#ifndef VL_MKENUM
	#define VL_MKENUM(X_,Y_) X_##Y_,
#endif

// - antes de usar:
//     definir VL_MAT_IDX_STEP e voltar a undef quando acabar
//	   para mudar para transposta #VL_MAT_IDX
#ifndef VL_MAT_IDX1_CURR_ROW 
	#define VL_MAT_IDX1_CURR_ROW 0
#endif
#ifndef VL_MAT_IDX2_CURR_ROW 
	#define VL_MAT_IDX2_CURR_ROW 0
#endif
#ifndef VL_MAT_IDX1_CURR_COL
	#define VL_MAT_IDX1_CURR_ROW 0
#endif
#ifndef VL_MAT_IDX2_CURR_COL 
	#define VL_MAT_IDX2_CURR_ROW 0
#endif

#ifndef VL_MAT_IDX1_NORMAL
	#define VL_MAT_IDX1_NORMAL(ROW_,COL_)		VL_MAT_IDX1_PTR[(((VL_MAT_IDX1_CURR_COL)+COL_)*(VL_MAT_IDX1_STEP)) + ((VL_MAT_IDX1_CURR_ROW)+ROW_)]
	#define VL_MAT_IDX1_TRANSPOSE(ROW_,COL_)	VL_MAT_IDX1_PTR[(((VL_MAT_IDX1_CURR_ROW)+ROW_)*(VL_MAT_IDX1_STEP)) + ((VL_MAT_IDX1_CURR_COL)+COL_)]
	#define VL_MAT_IDX2_NORMAL(ROW_,COL_)		VL_MAT_IDX2_PTR[(((VL_MAT_IDX2_CURR_COL)+COL_)*(VL_MAT_IDX2_STEP)) + ((VL_MAT_IDX2_CURR_ROW)+ROW_)]
	#define VL_MAT_IDX2_TRANSPOSE(ROW_,COL_)	VL_MAT_IDX2_PTR[(((VL_MAT_IDX2_CURR_ROW)+ROW_)*(VL_MAT_IDX2_STEP)) + ((VL_MAT_IDX2_CURR_COL)+COL_)]
#endif

#ifndef VL_MAT_IDX1
	#define VL_MAT_IDX1							VL_MAT_IDX1_NORMAL
#endif
#ifndef VL_MAT_IDX2
	#define VL_MAT_IDX2							VL_MAT_IDX2_NORMAL
#endif


