	// alinhamento de variavel: ajusta o valor à régua RULER - exemplo (v,8) alinha a 8 (ex. 8 bytes)
	#define VL_ALIGNA(VAR, RULER) { const SW32 VAR##____r = (VAR % RULER); VAR += ((VAR##____r)==0)? 0: (RULER-(VAR##____r)); }
	// 
	#define VL_MALIGNA(x) __declspec(align(x))
	// 
	#define VL_MAT_MALIGNA(KIND,PTR0,PTR,BYTE_STEP,BYTE_STRIDE, BYTE_REAL_SZ,BYTE_ALIGN,M,N) \
						BYTE_STRIDE		= (N*sizeof(KIND))%BYTE_ALIGN;		\
						BYTE_STEP		= (N*sizeof(KIND)) + BYTE_STRIDE;	\
						BYTE_REAL_SZ	= BYTE_STEP*M + BYTE_ALIGN;			\
						PTR0			= (KIND*)new SW8[BYTE_REAL_SZ];	\
						PTR				= (KIND*)(  (SW8*)PTR0 + (  ((long long)PTR0) % BYTE_ALIGN) );

	//casts para a variavel como T* para poder
	//acedida como array
		//declara, com o nome terminado em "Arr" 
		#define VL_ASARR_DECL(T,ID)					T* ID##Arr = ((T*)(&(ID)));
		//uso momentaneo:
		// cast
		#define VL_ASARR(T,ID)						((T*)(&(ID)))
		//indexa
		#define VL_ASARR_IDX(T,ID,n)				(((T*)(&(ID)))[(n)])
		//indexa e soma
		#define VL_ASARR_SUM(T,ID,n,TOSUM_)			((T*)(&(ID)))[(n)]+=(TOSUM_);
		//troca valores 
		#define VL_ASARR_SWAP(T,ID,idx0,idx1)		{ T TEMP_____ = (((T*)(&(ID)))[(idx0)]); (((T*)(&(ID)))[(idx0)])=(((T*)(&(ID)))[(idx1)]); (((T*)(&(ID)))[(idx1)])=TEMP_____; }
#endif
#endif

