	//VETOR 2

	#define VL_CENTER2(a,b,c) c[0] = 0.5f*(VL_FP)(a[0]+b[0]); c[1] = 0.5f*(VL_FP)(a[1]+b[1]);
	#define VL_SUB2(b,a,DST) DST[0]=b[0]-a[0]; DST[1]=b[1]-a[1]; 
	#define VL_IP2(a,b,DST) DST=a[0]*b[0]+a[1]*b[1];
	#define VL_TRACE2(a) (a[0]+a[3])
	#define	VL_DET2(a)	 (a[0]*a[3]-a[1]*a[2])
	#define VL_VNORM2(a) (sqrt(a[0]*a[0]+a[1]*a[1]))
	#define VL_CROSS2(a,b,DST) {  DST[0] = -b; \
								  DST[1] = a; }
	#define VL_TRANSPOSE2(SCR,DST) { DST[1] = SCR[2]; DST[2] = SCR[1]; DST[0] = SCR[0]; DST[3] = SCR[3]; }
	#define VL_SELFTRANSPOSE2(DT_, SRC_) { const DT_ a12 = SRC_[1]; SRC_[1] = SRC_[2]; SRC_[2] = a12;}
	#define VL_INV2(DT_, SRC_,DST_)  {const DT_ N_ = 1.0f/((VL_FP)(data[0]*data[3]-data[1]*data[2])); DST_[0] = SRC_[3]*N_; DST_[1] = -SRC_[1]*N_; DST_[2] = -SRC_[2]*N_; DST_[3] = SRC_[0]*N_; }

	//VETOR 3
	#define VL_ARR3_INTERPOL(A,B,DST,SC0,SC1) { (DST)[0] = ((VL_FP)((A)[0]))*(SC0) + ((VL_FP)((B)[0]))*(SC1); (DST)[1] = ((VL_FP)((A)[1]))*(SC0) + ((VL_FP)((B)[1]))*(SC1); (DST)[2] = ((VL_FP)((A)[2]))*(SC0) + ((VL_FP)((B)[2]))*(SC1); }
	#define VL_CENTER3(a,b,c) h[0] = 0.5f*(VL_FP)(a[0]+b[0]+c[0]); h[1] = 0.5f*(VL_FP)(a[1]+b[1]+c[1]); h[1] = 0.5f*(VL_FP)(a[1]+b[1]+c[2]);
	#define VL_ADD3(b,a,DST) DST[0]=b[0]+a[0]; DST[1]=b[1]+a[1]; DST[2]=b[2]+a[2];
	#define VL_ADDSCALAR3(sc,DST) DST[0]+=sc; DST[1]+=sc; DST[2]+=sc;
	#define VL_ADDSCALARSAT3(sc,SATMIN,SATMAX,DST) \
			DST[0] = MAX(SATMIN,MIN(SATMAX, DST[0]+sc));\
			DST[1] = MAX(SATMIN,MIN(SATMAX, DST[1]+sc));\
			DST[2] = MAX(SATMIN,MIN(SATMAX, DST[2]+sc));
	#define VL_SUB3(b,a,DST) DST[0]=b[0]-a[0]; DST[1]=b[1]-a[1]; DST[2]=b[2]-a[2];
	#define VL_IP3(A_,B_)  (A_[0]*B_[0]+A_[1]*B_[1]+A_[2]*B_[2])
	#define VL_SIP3(A_)  (A_[0]*A_[0]+A_[1]*A_[1]+A_[2]*A_[2])
	#define VL_CROSS3(a,b,DST) {  DST[0] = a[1]*b[2] - a[2]*b[1]; \
								  DST[1] = a[2]*b[0] - a[0]*b[2]; \
								  DST[2] = a[0]*b[1] - a[1]*b[0]; }
	#define VL_VNORM3(a) (sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]))

	#define VL_SELFTRANSPOSE3(DT_, DST_){ const DT_ a12 = DST_[1]; DST_[1] = DST_[3]; DST_[3] = a12; const DT_ a13 = DST_[2]; DST_[2] = DST_[6]; DST_[6] = a13; const DT_ a23 = DST_[5]; DST_[5] = DST_[7]; DST_[7] = a23;}
	#define VL_TRANSPOSE3(SRC_,DST_){ DST_[1] = SRC_[3]; DST_[3] = SRC_[1]; DST_[2] = SRC_[6]; DST_[6] = SRC_[2]; DST_[5] = SRC_[7]; DST_[7] = SRC_[5]; DST_[0] = SRC_[0]; DST_[4] = SRC_[4]; DST_[8] = SRC_[8]; }
	#define VL_INV3(DT_,DET3_,S0_,S1_,S2_,D0_,D1_,D2_)\
		{ const DT_ N_ = 1.0f/(DET3_); \
		D0_[0] = N_*(S1_[1]*S2_[2] - S1_[2]*S2_[1]); \
		D0_[1] = N_*(S0_[2]*S2_[1] - S0_[1]*S2_[2]); \
		D0_[2] = N_*(S0_[1]*S1_[2] - S0_[2]*S1_[1]); \
		D1_[0] = N_*(S1_[2]*S2_[0] - S1_[0]*S2_[2]); \
		D1_[1] = N_*(S0_[0]*S2_[2] - S0_[2]*S2_[0]); \
		D1_[2] = N_*(S0_[2]*S1_[0] - S0_[0]*S1_[2]); \
		D2_[0] = N_*(S1_[0]*S2_[1] - S1_[1]*S2_[0]); \
		D2_[1] = N_*(S0_[1]*S2_[0] - S0_[0]*S2_[1]); \
		D2_[2] = N_*(S0_[0]*S1_[1] - S0_[1]*S1_[0]);}

	// reflete V_(3x1) sobre o plano P_ (4x1)
	#define VL_HOUSEHOLDER3(DT_, P_, V_, DST_)					\
		{														\
			const DT_ N_ = 2.0f/VL_IP3(p_,p_);					\
			const DT_ a11 = N_*P_[0]*P_[0];						\
			const DT_ a12 = N_*P_[0]*P_[1];						\
			const DT_ a13 = N_*P_[0]*P_[2];						\
			const DT_ a22 = N_*P_[1]*P_[1];						\
			const DT_ a23 = N_*P_[1]*P_[2];						\
			const DT_ a33 = N_*P_[2]*P_[2];						\
			DST_[0] = (1.0f-a11)*V_[0]+a12*V_[1]+a13*V_[2];		\
			DST_[1] = (a12)*V_[0]+ (1.0f-a22*V_[1])+a23*V_[2];	\
			DST_[2] = (a13)*V_[0]+ (a23*V_[1])+(1.0f-a33*V_[2]);\
		}

	// criar linha homogenea ponto a e b
	#define VL_HLINE2_CREATE(DT_, l, a, b)			\
		{												\
			const DT_ v[] = {b[0] - a[0], b[1] - a[1]};	\
			l[0] = -v[1] ;								\
			l[1] =  v[0] ;								\
			l[2] =  a[0]*v[1] - a[1]*v[0];				\
			VL_FP n  = VL_VNORM3(l);					\
			l[0]=(VL_FP)l[0]/n;							\
			l[1]=(VL_FP)l[1]/n;							\
			l[2]=(VL_FP)l[2]/n;							\
		}


	//produto externo considerando a[2]=1 b[2]=1
	#define VL_CROSS3_HM(a,b,DST) {  DST[0] = a[1] - b[1]; DST[1] = b[0] - a[0]; DST[2] = a[0]*b[1] - a[1]*b[0];  }
	#define VL_TRACE3(R0,R1,R2) (R0[0]+R1[1]+R2[2])
	#define VL_EYE3(R0,R1,R2)  R0[1]=R0[2]=R1[0]=R1[2]=R2[0]=R2[1]=0; R0[0]=R1[1]=R2[2]=1;
