	#define VL_M43_x13_PROJ_INT(x, z, M, x2) { z =  x[0]*M[2]+x[1]*M[5]+x[2]*M[8]+M[11]; x2[0] = (SW32)((x[0]*M[0]+x[1]*M[3]+x[2]*M[6]+M[9])/z); x2[1] = (SW32)((x[0]*M[1]+x[1]*M[4]+x[2]*M[7]+M[10])/z); }

