	#define VL_K33_xy(K,x,y,x2) {  x2[0] = x*K[0]+K[2]; x2[1] = y*K[4]+K[5]; x2[2] = 1; }

	// homografia 
	// matriz de perspetiva 3x3 para um
	// retangulo x0,y0,w,h, dada matriz de rotação r 3x3
	#define VL_M33_RECT_PERSP(dst, r, x0, y0, w, h) VL_ARR9(dst,  (r[0]*w + r[6]*(w/2 + x0))/w, (r[1]*w + r[7]*(w/2 + x0))/h, w/2 + x0 - ((r[0]*w + r[6]*(w/2 + x0))*(w + 2*x0))/(2*w) - ((r[1]*w + r[7]*(w/2 + x0))*(h + 2*y0))/(2*h),\
													(h*r[3] + r[6]*(h/2 + y0))/w, (h*r[4] + r[7]*(h/2 + y0))/h, h/2 + y0 - ((h*r[4] + r[7]*(h/2 + y0))*(h + 2*y0))/(2*h) - ((h*r[3] + r[6]*(h/2 + y0))*(w + 2*x0))/(2*w), \
													r[6]/w,                       r[7]/h,                                                1 - (r[6]*(w + 2*x0))/(2*w) - (r[7]*(h + 2*y0))/(2*h))

	// homografia 
	// matrizes de perspetiva 3x3 para rotação dum
	// retangulo x0,y0,w,h por um angulo ang para no eixo X,Y,Z
	#define VL_M33_RECT_PERSPX(dst, ang, x0, y0, w, h) \
				{   const VL_FP sANG = cos(ang), cANG = sin(ang), h2 = 2*h, ho2 = h/2, wo2 = w/2; \
					VL_ARR9(dst,	1,       (cANG*(wo2 + x0))/h, -(cANG*(h + 2*y0)*(wo2 + x0))/(h2), \
									0, (h*sANG + cANG*(ho2 + y0))/h, ho2 + y0 - ((h + 2*y0)*(h*sANG + cANG*(ho2 + y0)))/(h2), \
									0,                    cANG/h,                           1 - (cANG*(h + 2*y0))/(h2))\
				}

	#define VL_M33_RECT_PERSPY(dst, ang, x0, y0, w, h) \
				{  const VL_FP cANG = cos(ang), sANG = sin(ang), w2 = 2*w, ho2 = h/2, wo2 = w/2; \
					VL_ARR9(dst, (cANG*w - sANG*(wo2 + x0))/w, 0, wo2 + x0 - ((cANG*w - sANG*(wo2 + x0))*(w + 2*x0))/(w2),\
								  -(sANG*(ho2 + y0))/w, 1,                    (sANG*(ho2 + y0)*(w + 2*x0))/(w2),\
								  -sANG/w,              0,                    (sANG*(w + 2*x0))/(w2) + 1)\
				}
  
	#define VL_M33_RECT_PERSPZ(dst, ang, x0, y0, w, h) \
				{  const VL_FP cANG = cos(ang), sANG = sin(ang); \
						VL_ARR9(dst, cANG, (sANG*w)/h, w/2 + x0 - (cANG*(w + 2*x0))/2 - (sANG*w*(h + 2*y0))/(2*h),\
									 -(h*sANG)/w,       cANG, h/2 + y0 - (cANG*(h + 2*y0))/2 + (h*sANG*(w + 2*x0))/(2*w),\
											   0,          0,                                                          1)\
				 }
		
			
	#define VL_MAT_FROM_ZROT(DT_, DSTR0_, DSTR1_,ANG_)			\
		{													\
		const DT_ C = cos(ANG_); const DT_ S = sin(ANG_);	\
		(DSTR0_)[0] = C; (DSTR0_)[1] = -S;					\
		(DSTR1_)[0] = S; (DSTR1_)[1] =  C;					\
		}

	#define VL_ANGLEAXIS_FROM_MAT(DT, V_, SRC0_, SRC1_, SRC2_)		\
	{																\
		const DT mult = sin((SRC0_[0]+SRC1_[1]+SRC2_[2]-1)/2)*2.0f;	\
		V_[0] =mult * (SRC2_[1]-SRC1_[2]);							\
		V_[1] =mult * (SRC0_[2]-SRC2_[0]);							\
		V_[2] =mult * (SRC1_[0]-SRC0_[1]);							\
	}

	#define VL_MAT_FROM_ANGLEAXIS(DT, DSTR0_, DSTR1_, DSTR2_, V_)			\
		{																	\
			const DT x   = V_[0];											\
			const DT y   = V_[1];											\
			const DT z   = V_[2];											\
			const DT c   = cos(theta);										\
			const DT s   = sin(theta);										\
			const DT C   = 1-c;												\
			const DT xs  = x*s;     										\
			const DT ys  = y*s;												\
			const DT zs  = z*s;												\
			const DT xC  = x*C;        										\
			const DT yC  = y*C;												\
			const DT zC  = z*C;												\
			const DT xyC = x*yC;       										\
			const DT yzC = y*zC;       										\
			const DT zxC = z*xC;											\
			(DSTR0_)[0]=x*xC+c; (DSTR0_)[1]=xyC-zs; (DSTR0_)[2]=zxC+ys;		\
			(DSTR1_)[0]=xyC+zs; (DSTR1_)[1]=y*yC+c; (DSTR1_)[2]=yzC-xs;		\
			(DSTR2_)[0]=zxC-ys; (DSTR2_)[1]=yzC+xs; (DSTR2_)[2]=z*zC+c;		\
		}

	#define VL_ANGLEAXIS_TO_QUATERNION(DT, Q_, V_)								\
		{ 																	\
			const DT norm_ = sqrt(V_[0]*V_[0]+V_[1]*V_[1]+V_[2]*V_[2]);	\
			if (norm_){														\
			const DT ang2_ = norm_/2;									\
			const DT s_ = sin(ang2_)/norm_;								\
			Q_[0]=cos(ang2_);												\
			Q_[1]=s_*V_[0];													\
			Q_[2]=s_*V_[1];													\
			Q_[3]=s_*V_[2]};												\
		}

	#define VL_QUATERNION_TO_ANGLEAXIS(DT, V_, Q_)									\
		{ 																		\
			const DT a2_ = acos(Q_[0]);										\
			if (a2_!=0)															\
			{																	\
				const DT s_ = (a2_*2)/sin(a2_);								\
				const DT norm_ = (Q_[1]*Q_[1]+ Q_[2]*Q_[2]+ Q_[3]*Q_[3]);	\
				V_[0] = Q_[1]*s_;												\
				V_[1] = Q_[2]*s_;												\
				V_[2] = Q_[3]*s_;												\
																				\
			}}

#endif
#endif


// 8. defines de soluções de polinomios com defines
#ifdef VL_ARRAY_INCLUDES_POLYS
#ifndef VL_ARRAY_INCLUDES_POLYS_
#define VL_ARRAY_INCLUDES_POLYS_
	#define VL_FRES_POLY2(res,x,a1,a0)		 { res = (a1)*(x)*(x) + (x); }
	#define VL_FRES_POLY3(res,x,a2,a1,a0)	 { const VL_FP sqx2 = (x)*(x); res = (a2)(sqx2*(x)) + (a1)*sqx2 + (x); }
	#define VL_FRES_POLY4(res,x,a3,a2,a1,a0) { const VL_FP sqx2 = (x)*(x); res = (a3)*(sqx2*sqx2) + (a2)(sqx2*(x)) + (a1)*sqx2 + (x); }
	
	// raiz quadrada: ambas solucoes podem nao ser reais
	//  x = ( - a1 +- (a1^2 - 4*a2*a0)^(1/2) ) / (2 * a2)
	//             ----------------
	//                      ^						   
	//                      |
	//  EXTRA: sai D0, interior da raiz a2: expoente 2, a0: expoente 0
	#define VL_FRES_POLY2ROOT_(res_0, res_1, a2, a1, a0, D0) \
	{\
		D0 = (a1)*(a1)- 4*(a2)*(a0);				\
		const VL_FP sqrtn = sqrt(D0);				\
		const VL_FP n_= 2*(a2);						\
		res_0 = (-(a1)+sqrtn)/n_;					\
		res_1 = (-(a1)-sqrtn)/n_;					\
	}
	//	if (res_0<res_1) std::swap(res_0,res_1);\
	//
	#define VL_FRES_POLY2ROOT_EXTRA(res_0, res_1, a2, a1, a0, D0) \
	{	\
		VL_FRES_POLY2ROOT_(res_0, res_1, a2, a1, a0, D0)\
	}

	#define VL_FRES_POLY2ROOT(res_0, res_1, a2, a1, a0) \
	{\
		VL_FP D0;\
		VL_FRES_POLY2ROOT_EXTRA(res_0, res_1, a2, a1, a0, D0)\
	}
	namespace vl{ namespace poly3
	{
	   
		template<typename DT> // 
		inline W0  root
			(DT& res_0, DT& res_1, DT& res_2,  SW32& nsol, DT& D_,
				DT a, DT b, DT c, DT d ) 
		{
			const VL_FP b2 = (b)*(b);			
			const VL_FP a3 = 3*a;
			const VL_FP p = ( c - (b2/(3*a))  )/a;
			VL_FP q = -( d + (2*b2*b)/(27*(a*a)) - (b*c)/(a3)  )/a;
			const VL_FP q2 = q*q;
			const VL_FP p3 = p*p*p;

			D_   = ((q2)/4.0f) + ((p3)/27.0f);


			if (D_<0) //solução geometrica
			{
				q=-q;
				const VL_FP xL_   =  2.0f * sqrt(-p/3.0f);
				const VL_FP acos_ =  (1.0f/3.0f)* acos(((3*q)/(2*p))*sqrt(-3.0f/p));
				VL_FP y0_ = b/(a3);
				res_0 = xL_ * cos( acos_ ) - y0_;
				res_1 = xL_ * cos( acos_ - VL_M_PI2O3 ) - y0_;
				res_2 = xL_ * cos( acos_ - VL_M_PI4O3 ) - y0_;
				nsol = 3;
			}
			else //solução de cardano
			{
				VL_FP r[2], rD0;
				VL_FRES_POLY2ROOT_(r[0], r[1], 1.0f, q, (-(p3)/27.0f), rD0);
				SW32 idx_ = (fabs(r[0]) < fabs(r[1])) ? 1:0;
				VL_FP t = pow((VL_FP)r[idx_],(VL_FP)(1.0f/3.0f));
				VL_FP s = p/(3*t);
				VL_FP y = (s-t);
				res_0 = y - b/(a3);
				nsol = 1;
			}
		}
	};};
#endif
#endif

